de"},"boldo":{"hours":30,"yield":10,"xp":10,"herbYield":"boldo"},"manjericao":{"hours":32,"yield":10,"xp":10,"herbYield":"manjericao"},"pega_pinto":{"hours":32,"yield":10,"xp":10,"herbYield":"pega_pinto"},"jureminha":{"hours":34,"yield":11,"xp":11,"herbYield":"jureminha"},"alecrim":{"hours":34,"yield":11,"xp":11,"herbYield":"alecrim"},"pinheiro_natal":{"hours":48,"yield":15,"xp":42,"wood":"pinheiro"},"eucalipto":{"hours":42,"yield":18,"xp":45,"wood":"eucalipto","leafId":"folha_eucalipto"},"pinha":{"hours":46,"yield":14,"xp":48,"wood":"araucaria"},"arvore_garrafa":{"hours":54,"yield":16,"xp":52,"wood":"arvore_garrafa"},"nepenthes":{"hours":58,"yield":12,"xp":55,"herbYield":"nepenthes"},"uvaia":{"hours":64,"yield":18,"xp":62,"fruitCrop":"uvaia"},"cambuca":{"hours":70,"yield":20,"xp":68,"fruitCrop":"cambuca"}}'::jsonb;v_crop jsonb;v_tree_cfg jsonb;v_crop_id text;v_tree_id text;v_root text;
 v_count integer;v_remaining integer;v_now_ms bigint:=(extract(epoch from now())*1000)::bigint;v_total_hours numeric;v_planted_at numeric;v_progress numeric:=0;
 v_helper_xp numeric;v_owner_xp numeric;v_helper_level integer;v_owner_level integer;v_helper_last integer;v_owner_last integer;v_helper_bonus integer:=0;v_owner_bonus integer:=0;
 v_label text;v_leaf text;v_inventory_key text;
begin
 if v_uid is null then raise exception 'É necessário entrar na conta.';end if;
 if p_owner is null or p_owner=v_uid then raise exception 'Fazenda inválida.';end if;
 if p_area not in('farm','orchard','forest') then raise exception 'Área de visita inválida.';end if;
 if not exists(select 1 from public.social_friendships f where f.user_low=least(v_uid,p_owner) and f.user_high=greatest(v_uid,p_owner)) then raise exception 'Você precisa ser amigo deste jogador para ajudar na fazenda.';end if;
 if exists(select 1 from public.social_farm_visit_settings s where s.user_id=p_owner and s.allow_friend_visits=false) then raise exception 'Este jogador bloqueou visitas e ajudas na fazenda.';end if;
 if not exists(select 1 from pg_catalog.pg_timezone_names z where z.name=v_timezone) then raise exception 'Fuso horário inválido.';end if;
 v_today:=(now() at time zone v_timezone)::date;
 if p_area='farm' and (p_slot is null or p_slot<0 or p_slot>71) then raise exception 'Canteiro inválido.';end if;
 if p_area='orchard' and (p_slot is null or p_slot<0 or p_slot>7) then raise exception 'Espaço do Pomar inválido.';end if;
 if p_area='forest' and (p_slot is null or p_slot<0 or p_slot>35) then raise exception 'Espaço da Mata inválido.';end if;
 insert into public.social_help_friend_daily_usage(helper_id,usage_date,interactions,timezone) values(v_uid,v_today,0,v_timezone) on conflict(helper_id) do nothing;
 select case when u.usage_date=v_today then u.interactions else 0 end into v_used from public.social_help_friend_daily_usage u where u.helper_id=v_uid for update;
 v_used:=coalesce(v_used,0);v_green_award:=case when v_used<15 then 1 else 0 end;
 perform fs.user_id from public.farm_saves fs where fs.user_id in(v_uid,p_owner) order by fs.user_id for update;
 select fs.state,fs.revision into v_helper_state,v_helper_revision from public.farm_saves fs where fs.user_id=v_uid;
 if not found or v_helper_state is null then raise exception 'Seu salvamento na nuvem não foi encontrado. Sincronize a fazenda.';end if;
 select fs.state,fs.revision into v_owner_state,v_owner_revision from public.farm_saves fs where fs.user_id=p_owner;
 if not found or v_owner_state is null then raise exception 'O salvamento desta fazenda não foi encontrado.';end if;
 if not exists(select 1 from public.social_friendships f where f.user_low=least(v_uid,p_owner) and f.user_high=greatest(v_uid,p_owner)) then raise exception 'A amizade não está mais ativa.';end if;

 if p_area='farm' then
  if jsonb_typeof(v_owner_state->'plots')<>'array' or jsonb_array_length(v_owner_state->'plots')<=p_slot then raise exception 'Canteiro não encontrado nesta fazenda.';end if;
  v_plot:=v_owner_state->'plots'->p_slot;
